/* ============================================================
   أطياب الجاسم (React) — سياسات تحقق/منع-تكرار خالصة (FE35)

   وحدة بلا أي اعتماد (لا React ولا شبكة) لتُختبر بلا واجهة:
     · shouldContinueVerify — نافذة التحقق المحدود لصفحة العودة:
       حدّ المحاولات (POLL_MAX) + حدّ جداري إجمالي (wallMs) لأن
       20×3s ليست دقيقة زمن حائط (الاستجابة نفسها تستغرق وقتاً).
       لا تعد بأي زمن للمشتري — القرار داخلي فقط.
     · newIdempotencyKey — مفتاح ثابت لكل طلب منطقي واحد
       (إلغاء شحنة/إعادة إرسال آمنة) — يُولَّد مرة ويُعاد استعماله،
       لا يُولَّد من جديد عند كل timeout (بلا مفتاح/سياسة آمنة
       لا إعادة تلقائية).
   ============================================================ */

/* هل نواصل التحقق؟ المدخل: { tries (المحاولات المستهلكة), pollMax,
   startedAtMs, nowMs, wallMs (الحد الجداري الإجمالي بالمللي) }.
   المخرج: { cont: true } أو { cont: false, reason: "budget"|"wall" }. */
export function shouldContinueVerify(input) {
  const o = input || {};
  const tries = Number(o.tries);
  const pollMax = Number(o.pollMax);
  const wall = Number(o.wallMs);
  const start = Number(o.startedAtMs);
  const now = o.nowMs != null ? Number(o.nowMs) : Date.now();
  if (Number.isFinite(pollMax) && Number.isFinite(tries) && tries >= pollMax) {
    return { cont: false, reason: "budget" };
  }
  if (Number.isFinite(wall) && wall > 0 && Number.isFinite(start) && start > 0) {
    if (now - start >= wall) return { cont: false, reason: "wall" };
  }
  return { cont: true };
}

/* مفتاح منع تكرار لعملية منطقية واحدة — يُولَّد مرة واحدة لكل طلب
   (إلغاء شحنة مثلاً) ويُمرَّر مع كل إعادة عرض/ضغطة لنفس الطلب. */
export function newIdempotencyKey(prefix) {
  const p = String(prefix == null || prefix === "" ? "atyab" : prefix);
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) {
      return p + "-" + crypto.randomUUID();
    }
  } catch (e) {}
  const rnd = Math.floor(Math.random() * 1e9).toString(36) + Date.now().toString(36);
  return p + "-" + rnd;
}
