function parseEnvFlag(v) {
  var s = String(v == null ? "" : v).trim().toLowerCase();
  return s === "1" || s === "true" || s === "yes" || s === "on";
}

function resolveSimulationRequested() {
  try {
    if (typeof process !== "undefined" && process.env && process.env.REACT_APP_SHIPPING_SIMULATION != null) {
      return parseEnvFlag(process.env.REACT_APP_SHIPPING_SIMULATION);
    }
  } catch (e) {}
  try {
    if (typeof window !== "undefined" && window.__SHIPPING_SIMULATION__ != null) {
      return !!window.__SHIPPING_SIMULATION__;
    }
  } catch (e) {}
  return false;
}

function isProductionBuild() {
  try {
    if (typeof process !== "undefined" && process.env && process.env.NODE_ENV === "production") return true;
  } catch (e) {}
  return false;
}

/* ★ الطلب الصريح من البيئة — لا true ثابتة تخفي عدم التوافق. */
var SIM_REQUESTED = resolveSimulationRequested();

/* ★ حارس الإصدار المضلل: إنتاج + محاكاة = خطأ صريح (يفشل البناء عبر
   scripts/check-shipping-env.js ويفشل التشغيل هنا أيضاً). */
export function assertProductionShippingConfig() {
  if (isProductionBuild() && SIM_REQUESTED) {
    throw new Error("SHIPPING_SIMULATION forbidden in production build (REACT_APP_SHIPPING_SIMULATION must be unset/false)");
  }
}

try { assertProductionShippingConfig(); } catch (e) {
  /* ★ في الإنتاج نُسقط للمحاكاة الآمنة: نعطّلها ونرمي عند أول استعمال
     وهمي بدل عرض بيانات مضللة. */
  if (isProductionBuild()) SIM_REQUESTED = false;
}

