export function isTestId(id) {
  return /^TEST-/i.test(String(id == null ? "" : id));
}

export function assertNoTestIdsInRealMode(ids) {
  if (SHIPPING_SIMULATION) return;
  var list = Array.isArray(ids) ? ids : [ids];
  for (var i = 0; i < list.length; i++) {
    if (isTestId(list[i])) {
      throw new Error("TEST-* provider id forbidden in real mode: " + String(list[i]));
    }
  }
}

