/* ---------- تطبيع خالص ---------- */

export function normalizeEmirates(payload, simulated) {
  var p = payload || {};
  var raw = Array.isArray(p) ? p : (Array.isArray(p.items) ? p.items : []);
  var items = raw.map(function (r) {
    var o = r || {};
    return {
      id: String(o.id != null ? o.id : (o.emirateId != null ? o.emirateId : "")),
      nameAr: String(o.nameAr != null ? o.nameAr : (o.name != null ? o.name : "")),
      nameEn: String(o.nameEn != null ? o.nameEn : (o.name != null ? o.name : "")),
      /* ★ OP1: رمز المزود من الباك (اختياري حتى تثبيت الأسماء النهائية). */
      providerCode: String(o.providerCode != null ? o.providerCode : (o.ProviderCode != null ? o.ProviderCode : ""))
    };
  }).filter(function (o) { return !!o.id; });
  return {
    items: items,
    updatedAt: String(p.updatedAt || p.UpdatedAt || ""),
    simulated: !!simulated
  };
}

export function normalizeLocations(payload, simulated) {
  var p = payload || {};
  var raw = Array.isArray(p) ? p : (Array.isArray(p.items) ? p.items : (Array.isArray(p.locations) ? p.locations : []));
  var items = raw.map(function (r) {
    var o = r || {};
    return {
      id: String(o.id != null ? o.id : (o.locationId != null ? o.locationId : "")),
      emirateId: String(o.emirateId != null ? o.emirateId : (o.EmirateId != null ? o.EmirateId : "")),
      nameAr: String(o.nameAr != null ? o.nameAr : (o.name != null ? o.name : "")),
      nameEn: String(o.nameEn != null ? o.nameEn : (o.name != null ? o.name : "")),
      /* ★ OP1: رمز المزود من الباك (اختياري حتى تثبيت الأسماء النهائية). */
      providerCode: String(o.providerCode != null ? o.providerCode : (o.ProviderCode != null ? o.ProviderCode : ""))
    };
  }).filter(function (o) { return !!o.id; });
  return {
    items: items,
    updatedAt: String(p.updatedAt || p.UpdatedAt || ""),
    simulated: !!simulated
  };
}

/* ★ منع اختيار منطقة ليست ضمن الإمارة — خالصة (تُختبر بلا React). */
export function locationBelongsTo(items, emirateId, locationId) {
  var list = Array.isArray(items) ? items : [];
  var eid = String(emirateId == null ? "" : emirateId);
  var lid = String(locationId == null ? "" : locationId);
  if (!eid || !lid) return false;
  for (let i = 0; i < list.length; i++) {
    const o = list[i] || {};
    if (String(o.id) === lid) return String(o.emirateId || "") === eid;
  }
  return false;
}

export function providerDisplayName(items, id, lang) {
  var list = Array.isArray(items) ? items : [];
  var want = String(id == null ? "" : id);
  for (let i = 0; i < list.length; i++) {
    const o = list[i] || {};
    if (String(o.id) === want) {
      if (lang === "en") return String(o.nameEn || o.nameAr || want);
      return String(o.nameAr || o.nameEn || want);
    }
  }
  return "";
}

export function providerDisplayNameOf(items, id, lang) {
  return providerDisplayName(items, id, lang);
}

/* جسم تحقق العنوان — لا ClientNo أبداً. */
/* جسم التحقق/الربط — ints مطابقة لـv41 (AddressValidationRequest).
   0/0 مسموح لفحص الربط المحفوظ (قراءة فقط). لا ClientNo أبداً. */
export function buildAddressValidationBody(input) {
  const o = input || {};
  function numId(v) {
    if (v == null || v === "") return 0;
    const n = Number(v);
    return Number.isFinite(n) && n > 0 ? Math.round(n) : 0;
  }
  const body = {
    addressId: o.addressId != null ? Math.round(Number(o.addressId)) || 0 : 0,
    providerEmirateId: numId(o.providerEmirateId),
    providerLocationId: numId(o.providerLocationId)
  };
  /* ★ OP1: رمز المزود — يُرسَل فقط عند توفره من قوائم الباك (الأسماء
     النهائية تثبت بين الطرفين) — غيابه يُبقي جسم v41 بلا تغيير. */
  const pc = String(o.providerCode != null ? o.providerCode : (o.ProviderCode != null ? o.ProviderCode : "")).trim();
  if (pc) body.providerCode = pc;
  return body;
}

/* تطبيع رد التحقق: { valid, errors[] } — بلا كشف خام. */
/* تطبيع رد التحقق/الربط: { valid, errors[] } — يقبل camel/PascalCase. بلا كشف خام. */
export function normalizeAddressValidation(payload) {
  const p = payload || {};
  const v = (p.valid !== undefined ? p.valid : p.Valid);
  const valid = v === true || String(v).toLowerCase() === "true";
  const rawErrs = (p.errors !== undefined ? p.errors : p.Errors);
  const errs = Array.isArray(rawErrs) ? rawErrs.map(String) : [];
  return { valid: !!valid, errors: errs };
}
/* فحص صريح: HTTP 200 وحده لا يثبت نجاح الربط — يلزم valid===true بلا أخطاء. */
export function isBindingSaveOk(norm) {
  const n = norm || {};
  return n.valid === true && (!Array.isArray(n.errors) || n.errors.length === 0);
}

/* ---------- طبقة التطبيع الواحدة لحالات R40 (حرفية) ---------- */

/* Canonical key لكل كود باك فعلي (بما فيه PascalCase الحالية).
   لا ترتيب رقمي محلي ولا استنتاج خطي — الجدول وحده يحدد النهائية. */
/* أكواد العرض التسعة في v41 (النهائية: delivered/cancelled/returned فقط).
   الداخلية (Ready/Created/DispatchUnknown/...) محظورة هنا — ظهورها كسر عقد. */
var V41_STATUS_META = {
  preparing: { ar: "قيد التجهيز", en: "Preparing", final: false },
  registered: { ar: "مسجلة لدى شركة الشحن", en: "Registered", final: false },
  in_transit: { ar: "في الطريق", en: "In transit", final: false },
  delivered: { ar: "تم التوصيل", en: "Delivered", final: true },
  cancellation_requested: { ar: "طلب إلغاء قيد المعالجة", en: "Cancellation requested", final: false },
  cancelled: { ar: "ملغاة", en: "Cancelled", final: true },
  returning: { ar: "قيد الإرجاع", en: "Returning", final: false },
  returned: { ar: "مرتجعة", en: "Returned", final: true },
  attention: { ar: "تحتاج متابعة", en: "Needs follow-up", final: false }
};
/* ★ التطبيع الوحيد: خام الباك → canonical. كل صيغ الباك الحالية هنا. */
/* ★ التطبيع الوحيد v41: أكواد العرض التسعة فقط.
   أي كود داخلي (Ready/Created/DispatchUnknown/CancelRequested/...) أو صيغة غريبة
   تُترك كما هي ليُكتشف كسر العقد عبر isV41ContractMismatch — لا تخمين substring. */
export function canonicalShipmentStatusCode(raw) {
  var s = String(raw == null ? "" : raw).trim();
  if (!s) return "";
  var low = s.toLowerCase().replace(/[\s-]+/g, "_");
  if (V41_STATUS_META[low]) return low;
  return low;
}
/* كسر عقد v41: إصدار غير v41 أو كود خارج التسعة — توقف + رسالة صريحة. */
export function isV41ContractMismatch(shipment) {
  const o = shipment || {};
  if (o.contractVersion != null && String(o.contractVersion) !== "" && String(o.contractVersion) !== "v41") return true;
  const c = String(o.statusCode || "");
  if (!c) return false;
  return !V41_STATUS_META[c];
}

/* تطبيع v41 الكامل — يقرأ كل حقول العقد الفعلي بما فيها contractVersion
   وstatusReasonCode وshouldPoll وpollAfterSeconds وlabelAr/messageAr. */
export function normalizeShipment(payload, simulated) {
  const p = payload || {};
  const oid = p.orderId != null ? Number(p.orderId) : (p.OrderId != null ? Number(p.OrderId) : 0);
  var rawCode = p.statusCode != null ? p.statusCode : (p.StatusCode != null ? p.StatusCode : (p.status != null ? p.status : (p.Status != null ? p.Status : (p.state != null ? p.state : ""))));
  rawCode = String(rawCode == null ? "" : rawCode);
  var canon = canonicalShipmentStatusCode(rawCode);
  var hasShipment = true;
  if (p.hasShipment === false || p.HasShipment === false) hasShipment = false;
  if (!rawCode && !canon) hasShipment = false;
  function boolOf(v) { return v === true || String(v || "").toLowerCase() === "true"; }
  function strOf() {
    for (let i = 0; i < arguments.length; i++) {
      const v = arguments[i];
      if (v != null && String(v) !== "") return String(v);
    }
    return "";
  }
  const contractVersion = strOf(p.contractVersion, p.ContractVersion);
  const statusReasonCode = strOf(p.statusReasonCode, p.StatusReasonCode, p.reasonCode, p.ReasonCode);
  const labelAr = strOf(p.labelAr, p.LabelAr);
  const messageAr = strOf(p.messageAr, p.MessageAr);
  let shouldPoll = null;
  if (p.shouldPoll !== undefined && p.shouldPoll !== null) shouldPoll = boolOf(p.shouldPoll);
  else if (p.ShouldPoll !== undefined && p.ShouldPoll !== null) shouldPoll = boolOf(p.ShouldPoll);
  let pollSec = (p.pollAfterSeconds != null ? Number(p.pollAfterSeconds) : (p.PollAfterSeconds != null ? Number(p.PollAfterSeconds) : NaN));
  if (!Number.isFinite(pollSec) || pollSec < 0) pollSec = NaN;
  let pollMs = (p.pollIntervalMs != null && Number(p.pollIntervalMs) > 0) ? Number(p.pollIntervalMs) : NaN;
  if (!Number.isFinite(pollMs) || pollMs <= 0) {
    pollMs = Number.isFinite(pollSec) && pollSec > 0 ? Math.round(pollSec * 1000) : SHIPMENT_ACTIVE_POLL_MS;
  }
  pollMs = Math.max(SHIPMENT_POLL_MIN_MS, Math.min(SHIPMENT_POLL_MAX_MS, pollMs));
  const out = {
    orderId: oid || 0,
    contractVersion: contractVersion || "",
    statusCode: canon,
    rawStatusCode: rawCode,
    statusReasonCode: String(statusReasonCode || ""),
    labelAr: String(labelAr || ""),
    messageAr: String(messageAr || ""),
    hasShipment: hasShipment,
    voucherNo: strOf(p.voucherNo, p.VoucherNo, p.trackingNumber),
    expectedDeliveryDate: strOf(p.expectedDeliveryDate, p.ExpectedDeliveryDate),
    lastUpdatedAt: strOf(p.lastUpdatedAt, p.LastUpdatedAt, p.updatedAt),
    isStale: boolOf(p.isStale !== undefined ? p.isStale : p.IsStale),
    canRequestCancellation: boolOf(p.canRequestCancellation !== undefined ? p.canRequestCancellation : p.CanRequestCancellation),
    pollIntervalMs: pollMs,
    pollAfterSeconds: Number.isFinite(pollSec) ? pollSec : Math.round(pollMs / 1000),
    simulated: !!simulated
  };
  out.shouldPoll = (shouldPoll === null || shouldPoll === undefined) ? null : !!shouldPoll;
  out.contractMismatch = isV41ContractMismatch(out);
  return out;
}

/* حالات العرض R40 — النهائي فرونت: delivered / cancelled / returned فقط.
   لا استنتاج delivered من التاريخ — الموثق وحده. */
/* حالات العرض v41 — النهائية: delivered / cancelled / returned فقط.
   لا استنتاج delivered من التاريخ — الموثقة وحدها.
   labelAr/messageAr من الخادم تُعرض كما هي عند توفرها (آمنة). */
export function shipmentStatusMeta(code, lang) {
  var canon = canonicalShipmentStatusCode(code);
  var hit = V41_STATUS_META[canon];
  if (hit) return { key: canon, label: lang === "en" ? hit.en : hit.ar, final: !!hit.final, known: true };
  if (!canon) return { key: "", label: lang === "en" ? "No shipment yet" : "لا توجد شحنة بعد", final: false, known: false, empty: true };
  return { key: canon || "unknown", label: lang === "en" ? "Shipment status unavailable" : "تعذّر قراءة حالة الشحنة", final: false, known: false };
}
/* نص آمن للعميل لحالة تحتاج متابعة: messageAr الخادمي أولاً (آمن)، ثم سبب عام.
   لا يخلط فشل الشحنة بفشل الدفع أبداً. */
export function shipmentAttentionText(shipment, lang) {
  const o = shipment || {};
  if (o.messageAr) return String(o.messageAr);
  if (o.labelAr) return String(o.labelAr);
  const en = lang === "en";
  const rc = String(o.statusReasonCode || "");
  if (/address_mapping_required/.test(rc)) return en ? "The address needs delivery-zone binding before dispatch." : "العنوان يحتاج استكمال ربط التوصيل (الإمارة والمنطقة) قبل الإرسال.";
  if (/dispatch_unknown_reconcile/.test(rc)) return en ? "Sent but unconfirmed — we reconcile without a second shipment." : "أُرسلت الشحنة لكن تأكيد الشركة لم يصل بعد — نتحقق منها دون إنشاء شحنة ثانية.";
  if (/needs_correction/.test(rc)) return en ? "The shipment needs correction before dispatch." : "بيانات الشحنة تحتاج تصحيحًا قبل الإرسال.";
  if (/rejected_by_provider/.test(rc)) return en ? "The carrier refused the shipment — contact customer service." : "رفضت الشركة استلام الشحنة — تواصل مع خدمة العملاء.";
  return shipmentStatusMeta(o.statusCode, lang).label;
}

export function isShipmentFinal(code) {
  return !!shipmentStatusMeta(code).final;
}

/* ★ قرار متابعة الشحنة (R40 §1): توقف عند النهائية أو المغادرة + backoff + حد. */
/* ★ قرار متابعة الشحنة (v41): shouldPoll=false يوقف فوراً حتى لو غير نهائية.
   shouldPoll=true لا يلغي حدود الوقت/المحاولات وbackoff ومنع التداخل.
   كسر العقد (إصدار/كود غريب) يوقف أيضاً برسالة صريحة. */
export function shouldContinueShipmentPoll(input) {
  var o = input || {};
  if (o.contractMismatch === true) return { cont: false, reason: "contract-mismatch" };
  if (o.shouldPoll === false) return { cont: false, reason: "server-stop" };
  var meta = shipmentStatusMeta(o.statusCode);
  if (meta.final) return { cont: false, reason: "final" };
  if (o.departed === true) return { cont: false, reason: "departed" };
  var attempts = Number(o.attempts);
  var maxA = o.maxAttempts != null ? Number(o.maxAttempts) : SHIPMENT_POLL_MAX_ATTEMPTS;
  if (Number.isFinite(maxA) && Number.isFinite(attempts) && attempts >= maxA) return { cont: false, reason: "budget" };
  var wall = o.maxDurationMs != null ? Number(o.maxDurationMs) : SHIPMENT_POLL_MAX_DURATION_MS;
  var start = Number(o.startedAtMs);
  var now = o.nowMs != null ? Number(o.nowMs) : Date.now();
  if (Number.isFinite(wall) && wall > 0 && Number.isFinite(start) && start > 0) {
    if (now - start >= wall) return { cont: false, reason: "wall" };
  }
  return { cont: true };
}

export function nextShipmentPollDelay(attempt, baseMs) {
  var a = Math.max(0, Number(attempt) || 0);
  var base = Number(baseMs) > 0 ? Number(baseMs) : SHIPMENT_ACTIVE_POLL_MS;
  base = Math.max(SHIPMENT_POLL_MIN_MS, Math.min(SHIPMENT_POLL_MAX_MS, base));
  var d = Math.round(base * Math.pow(1.25, Math.min(a, 6)));
  return Math.max(SHIPMENT_POLL_MIN_MS, Math.min(SHIPMENT_POLL_MAX_MS, d));
}

/* ---------- تنسيق تاريخ العقد (Asia/Dubai آمن — بلا إزاحة يوم بالUTC) ---------- */

function pad2(n) {
  const v = Number(n);
  return (v < 10 ? "0" : "") + String(v);
}

export function formatContractDay(value, lang) {
  const s = String(value == null ? "" : value).trim();
  if (!s) return { text: "", ms: 0 };
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  let d = null;
  let withTime = false;
  if (m) {
    d = new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), 12, 0, 0);
  } else if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    const p = s.split("-");
    d = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]), 12, 0, 0);
  } else {
    const ms = Date.parse(s);
    if (!Number.isFinite(ms)) return { text: "", ms: 0 };
    d = new Date(ms);
    withTime = !/T00:00(:00)?(\.000)?(Z|[+-]00:?00)?$/.test(s);
  }
  if (!d || isNaN(d.getTime())) return { text: "", ms: 0 };
  let text = pad2(d.getDate()) + "/" + pad2(d.getMonth() + 1) + "/" + d.getFullYear();
  if (withTime) text += " · " + pad2(d.getHours()) + ":" + pad2(d.getMinutes());
  void lang;
  return { text: text, ms: d.getTime() };
}

/* ---------- أخطاء آمنة للمشتري (شحن فقط — لا دمج مع فشل الدفع) ---------- */

export function classifyShippingError(err) {
  const data = (err && err.response && err.response.data) || {};
  /* ★ OP4 §F5: احتياط response.status — اتساقاً مع classifyTrackingError
     (المحاكيات والملفوفات تضع الحالة في response وحده). */
  const st = Number((err && err.status) || (err && err.response && err.response.status) || 0) || 0;
  const raw = String(data.code || data.reason || data.errorCode || data.error_code || "").trim().toLowerCase();
  const norm = raw.replace(/-/g, "_");
  if (norm === "address_mapping_required") {
    return { kind: "address_mapping_required", message: "عنوانك المحفوظ يحتاج استكمال ربط التوصيل (الإمارة والمنطقة) قبل طلب جديد." };
  }
  if (norm === "shipping_not_supported") {
    return { kind: "shipping_not_supported", message: "هذه المنطقة غير مدعومة للتوصيل حالياً — اختر منطقة أخرى." };
  }
  if (norm === "shipment_processing" || norm === "shipment_pending") {
    return { kind: "shipment_processing", message: "الشحنة قيد التجهيز لدى المتجر — تابع حالتها من «طلباتي»." };
  }
  if (norm === "cancellation_not_allowed") {
    return { kind: "cancellation_not_allowed", message: "تعذّر طلب الإلغاء لهذه الشحنة — راجع خدمة العملاء." };
  }
  if (!st || st === 0) {
    const code = String((err && err.code) || "");
    if (/TIMEOUT|ECONNABORTED/i.test(code)) {
      return { kind: "timeout", message: "تعذّر تحميل حالة الشحنة — تحقق من الاتصال ثم أعد المحاولة." };
    }
    return { kind: "network", message: "تعذّر تحميل حالة الشحنة — تحقق من الاتصال ثم أعد المحاولة." };
  }
  if (st === 404) {
    return { kind: "not_found", message: "لا توجد شحنة مسجلة لهذا الطلب بعد — غيابها الآن طبيعي." };
  }
  if (st === 503) {
    return { kind: "service_unavailable", message: "خدمة الشحن غير متاحة مؤقتًا — حاول لاحقًا. طلبك محفوظ ولا يتأثر." };
  }
  if (st === 422) {
    return { kind: "attention", message: "الشحنة تحتاج استكمالًا — راجع التفاصيل في «طلباتي»." };
  }
  return { kind: "unknown", message: "تعذّر قراءة حالة الشحنة الآن — حاول مجدداً بعد قليل." };
}

/* ---------- طبقة الشبكة (كاش + مشاركة وعد + محاكاة موسومة) ---------- */

var emiratesCache = { at: 0, data: null, promise: null };
var locationsCache = {};
var shipmentCache = {};

function freshEnough(at, ttl) {
  return at > 0 && (Date.now() - Number(at)) < ttl;
}

async function readJson(res) {
  const text = await res.text().catch(function () { return ""; });
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) { return null; }
}

function throwShipping(res, payload) {
  const err = new Error("shipping error");
  err.name = "ApiError";
  err.status = res.status;
  err.response = { status: res.status, data: payload };
  throw err;
}

export function clearShippingCache() {
  emiratesCache = { at: 0, data: null, promise: null };
  locationsCache = {};
  shipmentCache = {};
}

export function clearShipmentCacheFor(orderId) {
  const k = String(Number(orderId) || orderId || "");
  if (k && shipmentCache[k]) delete shipmentCache[k];
}

export async function fetchShippingEmirates(opts) {
  const o = opts || {};
  if (SHIPPING_SIMULATION) return normalizeEmirates(mockEmirates(), true);
  if (emiratesCache.data && freshEnough(emiratesCache.at, SHIPPING_EMIRATES_TTL_MS)) {
    return emiratesCache.data;
  }
  if (emiratesCache.promise) return emiratesCache.promise;
  const p = (async function () {
    const res = await authFetch(ENDPOINTS.shippingEmirates(), { method: "GET", signal: o.signal });
    const payload = await readJson(res);
    if (!res.ok) throwShipping(res, payload);
    const norm = normalizeEmirates(payload, false);
    emiratesCache = { at: Date.now(), data: norm, promise: null };
    return norm;
  })();
  emiratesCache.promise = p;
  try {
    return await p;
  } catch (e) {
    if (emiratesCache.promise === p) emiratesCache.promise = null;
    throw e;
  }
}

export async function fetchShippingLocations(emirateId, opts) {
  const o = opts || {};
  const eid = String(emirateId || "");
  if (!eid) throw new Error("missing emirate");
  assertNoTestIdsInRealMode([eid]);
  if (SHIPPING_SIMULATION) return normalizeLocations(mockLocations(eid), true);
  const hit = locationsCache[eid];
  if (hit && hit.data && freshEnough(hit.at, SHIPPING_LOCATIONS_TTL_MS)) return hit.data;
  if (hit && hit.promise) return hit.promise;
  const p = (async function () {
    const res = await authFetch(ENDPOINTS.shippingEmirateLocations(eid), { method: "GET", signal: o.signal });
    const payload = await readJson(res);
    if (!res.ok) throwShipping(res, payload);
    const norm = normalizeLocations(payload, false);
    locationsCache[eid] = { at: Date.now(), data: norm, promise: null };
    return norm;
  })();
  locationsCache[eid] = { at: (hit && hit.at) || 0, data: (hit && hit.data) || null, promise: p };
  try {
    return await p;
  } catch (e) {
    if (locationsCache[eid] && locationsCache[eid].promise === p) {
      locationsCache[eid] = { at: 0, data: null, promise: null };
    }
    throw e;
  }
}

export async function validateShippingAddress(body, opts) {
  const o = opts || {};
  const req = buildAddressValidationBody(body || {});
  assertNoTestIdsInRealMode([req.providerEmirateId, req.providerLocationId]);
  if (SHIPPING_SIMULATION) {
    const ids = mockEmirates().items.map(function (x) { return x.id; });
    const locs = mockLocations(req.providerEmirateId).items;
    const ok = ids.indexOf(req.providerEmirateId) !== -1 &&
      locationBelongsTo(locs, req.providerEmirateId, req.providerLocationId);
    return ok
      ? { valid: true, errors: [] }
      : { valid: false, errors: ["address_mapping_required"] };
  }
  const res = await authFetch(ENDPOINTS.shippingAddressValidate(), {
    method: "POST",
    body: req,
    signal: o.signal
  });
  const payload = await readJson(res);
  if (!res.ok) throwShipping(res, payload);
  return normalizeAddressValidation(payload);
}

/* ★ استعلام شحنة واحد مشترك لكل طلب — المستدعون يتشاركون الوعد نفسه. */
/* ★ حفظ الربط v41 — الكتابة الوحيدة (POST /api/shipping/address-binding).
   ينتظرها التسلسل: عنوان عادي → addressId حقيقي → binding → فحص valid/errors →
   إعادة جلب → تحقق التطابق. HTTP 200 وحده لا يكفي. */
export async function saveShippingAddressBinding(body, opts) {
  const o = opts || {};
  const req = buildAddressValidationBody(body || {});
  if (!req.addressId || req.addressId <= 0) throw new Error("missing addressId");
  if (!req.providerEmirateId || !req.providerLocationId) throw new Error("missing provider place");
  assertNoTestIdsInRealMode([req.providerEmirateId, req.providerLocationId]);
  if (SHIPPING_SIMULATION) {
    return { valid: true, errors: [], simulated: true };
  }
  const res = await authFetch(ENDPOINTS.shippingAddressBinding(), {
    method: "POST",
    body: req,
    signal: o.signal
  });
  const payload = await readJson(res);
  if (!res.ok) throwShipping(res, payload);
  const norm = normalizeAddressValidation(payload);
  norm.simulated = false;
  return norm;
}

export function fetchOrderShipment(orderId, opts) {
  const o = opts || {};
  const k = String(Number(orderId) || orderId || "");
  if (!k) return Promise.reject(new Error("missing order"));
  const hit = shipmentCache[k];
  if (hit && hit.data && !o.force) return Promise.resolve(hit.data);
  if (hit && hit.promise && !o.force) return hit.promise;
  const p = (async function () {
    if (SHIPPING_SIMULATION) return normalizeShipment(mockShipment(k), true);
    const res = await authFetch(ENDPOINTS.orderShipment(k), { method: "GET", signal: o.signal });
    const payload = await readJson(res);
    if (!res.ok) throwShipping(res, payload);
    return normalizeShipment(payload, false);
  })();
  shipmentCache[k] = { at: 0, data: (hit && hit.data) || null, promise: p };
  return p.then(function (norm) {
    shipmentCache[k] = { at: Date.now(), data: norm, promise: null };
    return norm;
  }, function (e) {
    if (shipmentCache[k] && shipmentCache[k].promise === p) {
      shipmentCache[k] = { at: 0, data: (hit && hit.data) || null, promise: null };
    }
    throw e;
  });
}

export async function requestShipmentCancellation(orderId, input, opts) {
  const o = opts || {};
  const inc = input || {};
  const k = String(Number(orderId) || orderId || "");
  if (!k) throw new Error("missing order");
  /* ★ مفتاح ثابت لكل طلب منطقي — يُولَّد مرة ويُعاد استعماله عند كل إعادة
     عرض/ضغطة/انقطاع لنفس الطلب (لا مفتاح عشوائي جديد لكل إعادة شبكة).
     persist عبر getOrCreateCancelIdempotencyKey عند توفر التخزين. */
  var key = String(inc.idempotencyKey || getOrCreateCancelIdempotencyKey(k, inc.reason) || newIdempotencyKey("ship-cancel-" + k));
  if (SHIPPING_SIMULATION) {
    return {
      requestId: "TEST-CANCEL-" + k,
      state: "pending",
      message: "تم إرسال طلب الإلغاء",
      idempotencyKey: key,
      simulated: true
    };
  }
  const res = await authFetch(ENDPOINTS.orderShipmentCancel(k), {
    method: "POST",
    body: { reason: String(inc.reason || "customer_request") },
    headers: { "Idempotency-Key": key },
    signal: o.signal
  });
  const payload = await readJson(res);
  if (!res.ok) throwShipping(res, payload);
  const p = payload || {};
  return {
    requestId: String(p.requestId || p.RequestId || ""),
    state: String(p.state || p.State || "pending"),
    message: String(p.message || p.detail || "تم إرسال طلب الإلغاء"),
    idempotencyKey: key,
    simulated: false
  };
}

/* ★ مفتاح منع التكرار الثابت لكل طلب منطقي — يبقى عبر إعادة العرض
   والانقطاع (نفس الطلب + نفس السبب = نفس المفتاح). */
var CANCEL_KEY_PREFIX = "atyab:ship-cancel-key:";
var cancelKeyMem = {};

export function cancelKeyStorageKey(orderId, reason) {
  return CANCEL_KEY_PREFIX + String(orderId) + ":" + String(reason || "customer_request");
}

export function getOrCreateCancelIdempotencyKey(orderId, reason) {
  var rk = String(reason || "customer_request");
  var sk = cancelKeyStorageKey(orderId, rk);
  try {
    if (cancelKeyMem[sk]) return cancelKeyMem[sk];
  } catch (e) {}
  try {
    if (typeof window !== "undefined" && window.localStorage) {
      var prev = window.localStorage.getItem(sk);
      if (prev) { cancelKeyMem[sk] = String(prev); return String(prev); }
      var nk = newIdempotencyKey("ship-cancel-" + String(orderId));
      try { window.localStorage.setItem(sk, nk); } catch (e2) {}
      cancelKeyMem[sk] = nk;
      return nk;
    }
  } catch (e) {}
  var fk = newIdempotencyKey("ship-cancel-" + String(orderId));
  try { cancelKeyMem[sk] = fk; } catch (e3) {}
  return fk;
}

export function clearCancelIdempotencyKey(orderId, reason) {
  var sk = cancelKeyStorageKey(orderId, reason);
  try { delete cancelKeyMem[sk]; } catch (e) {}
  try { if (typeof window !== "undefined" && window.localStorage) window.localStorage.removeItem(sk); } catch (e2) {}
}

/* ★ تخزين محلي لربط العنوان بالمزود — مسودة إدخال مؤقتة فقط (R40 §2).
   لا تكفي للسماح بإتمام الطلب ولا لإثبات حفظ الربط — المرجع المعتمد
   بيانات الباك (رد حفظ العنوان) حصراً. تُقرأ المسودة لتعبئة الحقول
   فقط، والبوابة تطلب تأكيدًا خادميًا. */
var PROVIDER_MAP_KEY = "atyab:providerMapDraft";

export function readProviderMapping(locationKey) {
  try {
    const raw = window.localStorage.getItem(PROVIDER_MAP_KEY);
    const o = raw ? JSON.parse(raw) : null;
    if (!o || typeof o !== "object") return null;
    const hit = o[String(locationKey == null ? "" : locationKey)];
    return hit && typeof hit === "object" ? hit : null;
  } catch (e) { return null; }
}

export function writeProviderMapping(locationKey, mapping) {
  try {
    const raw = window.localStorage.getItem(PROVIDER_MAP_KEY);
    const o = (raw ? JSON.parse(raw) : null) || {};
    o[String(locationKey == null ? "" : locationKey)] = mapping || null;
    window.localStorage.setItem(PROVIDER_MAP_KEY, JSON.stringify(o));
    return true;
  } catch (e) { return false; }
}

/* ★ هل الربط مؤكد خادميًا؟ (بيانات الباك مرجع — لا المسودة). */
export function isProviderBindingServerConfirmed(serverLocations, emirateId, locationId) {
  var list = Array.isArray(serverLocations) ? serverLocations : [];
  var eid = String(emirateId == null ? "" : emirateId);
  var lid = String(locationId == null ? "" : locationId);
  if (!eid || !lid) return false;
  for (var i = 0; i < list.length; i++) {
    var l = list[i] || {};
    if (String(l.providerEmirateId || "") === eid && String(l.providerLocationId || "") === lid) return true;
  }
  return false;
}

/* ★ إثبات أطياب-فقط (يُستعمل في اختبار التكامل): لا URL شركة هنا. */
export function assertAtyabOnlyEndpoints() {
  var urls = [
    ENDPOINTS.shippingEmirates(),
    ENDPOINTS.shippingEmirateLocations("X"),
    ENDPOINTS.shippingAddressValidate(),
    ENDPOINTS.shippingAddressBinding(),
    ENDPOINTS.orderShipment("1"),
    ENDPOINTS.orderShipmentCancel("1"),
    ENDPOINTS.shippingTracking(),
    ENDPOINTS.latestOrderShipment()
  ];
  urls.forEach(function (u) {
    var s = String(u || "");
    if (/^https?:\/\//i.test(s)) throw new Error("shipment endpoint must be relative Atyab API: " + s);
    if (/ainsoft|clientno|client-no/i.test(s)) throw new Error("company endpoint leaked: " + s);
  });
  return true;
}

/* ============================================================
   عقد OP1 — التتبع (5 حالات + progressStage + تفصيل الباك)

   المرجع: database/API-CONTRACT-OP1.md (عقد مقترح ملزم للتنسيق —
   يحتاج تنفيذ الطرفين واختبارهما؛ ليس وصفاً لمنشور حالياً).
   حتى ينفذ الباك OP1 فعلياً، هذه الطبقة تقبل شكل OP1 أولاً،
   وتحوّل شكل v41 الحالي (legacy) إلى نفس البنية مؤقتاً —
   التحويل موسوم OP1-FALLBACK هنا وفي الاختبارات.

   القواعد:
   · المجموعة (group) من الباك وحده: Pending/Returned/Cancelled/
     Delivered/InTheWay — لا قائمة 17 محلية ولا إعادة تصنيف.
   · المحطة من progressStage الموثوق وحده (0..4 أو null) — المجموعة
     وحدها لا تحددها. Half Delivered ضمن Delivered لكن بلا علامة
     اكتمال شامل ولا stage=4.
   · Returned/Cancelled مساران استثنائيان لا يتحركان للأمام.
   · Hold/Address Change لا يحركان العربة؛ Price Change لا يغيّر
     المبلغ محلياً؛ خطأ الشبكة لا يحوّل الشحنة لملغاة.
   · shouldPoll=false يوقف فوراً حتى لو غير نهائية.
   · العلني لا يعيد PII أبداً (يُبنى الجسم صراحة لا بالحذف).
   ============================================================ */

export var OP1_CONTRACT_VERSION = "OP1";
export var OP1_GROUPS = ["Pending", "Returned", "Cancelled", "Delivered", "InTheWay"];

/* المحطات الأربع (البرومبت §3): تسجيل الشحنة، استلامها من المتجر،
   في الطريق للمستلم، تم التسليم. stage=0 = قبل التسجيل. */
export var OP1_STAGES = [
  { stage: 0, ar: "بانتظار التسجيل لدى الشركة", en: "Awaiting carrier registration" },
  { stage: 1, ar: "تسجيل الشحنة", en: "Shipment registered" },
  { stage: 2, ar: "استلامها من المتجر", en: "Picked up from the store" },
  { stage: 3, ar: "في الطريق للمستلم", en: "On the way to you" },
  { stage: 4, ar: "تم التسليم", en: "Delivered" }
];

export function op1GroupMeta(group, lang) {
  var g = String(group == null ? "" : group);
  var en = lang === "en";
  if (g === "Pending") return { key: g, label: en ? "Pending" : "قيد الانتظار", final: false, exceptional: false };
  if (g === "InTheWay") return { key: g, label: en ? "On the way" : "في الطريق", final: false, exceptional: false };
  if (g === "Delivered") return { key: g, label: en ? "Delivered" : "تم التسليم", final: true, exceptional: false };
  if (g === "Cancelled") return { key: g, label: en ? "Cancelled" : "ملغاة", final: true, exceptional: true };
  if (g === "Returned") return { key: g, label: en ? "Returned" : "مرتجعة", final: true, exceptional: true };
  if (!g) return { key: "", label: en ? "No shipment yet" : "لا توجد شحنة بعد", final: false, exceptional: false, empty: true };
  return { key: g, label: en ? "Shipment status unavailable" : "تعذّر قراءة حالة الشحنة", final: false, exceptional: false, unknown: true };
}

export function isOP1Final(group) {
  return !!op1GroupMeta(group).final;
}

/* محلّل المرحلة الصارم المشترك (عقد OP1): عدد صحيح 0..4 أو null.
   null/undefined/"" → null؛ غير الصحيح (2.5) → null بلا تقريب؛
   خارج المجال → null. يُستعمل في op1StageMeta والتطبيع معاً. */
export function op1StrictStage(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === "string" && raw.trim() === "") return null;
  var n = Number(raw);
  if (!Number.isFinite(n)) return null;
  if (Math.round(n) !== n) return null;
  if (n < 0 || n > 4) return null;
  return n;
}

export function op1StageMeta(stage, lang) {
  /* null/undefined/"" → null (المجهول لا يتحول إلى «بانتظار التسجيل») */
  var n = op1StrictStage(stage);
  if (n === null) return null;
  for (var i = 0; i < OP1_STAGES.length; i++) {
    if (OP1_STAGES[i].stage === n) return { stage: n, label: lang === "en" ? OP1_STAGES[i].en : OP1_STAGES[i].ar };
  }
  return null;
}

/* تطبيع OP1 — يقبل شكل OP1 حصراً، وإلا مخرج كسر العقد (بلا تحويل legacy).
   isPublic=true: يُسقط حقول المسجل (orderId/invoiceNumber) دفاعياً. */
export function normalizeShipmentOP1(payload, simulated, isPublic) {
  const p = payload || {};
  function strOf() {
    for (let i = 0; i < arguments.length; i++) {
      const v = arguments[i];
      if (v != null && String(v) !== "") return String(v);
    }
    return "";
  }
  function boolOf(v) { return v === true || String(v || "").toLowerCase() === "true"; }
  /* تمييز الشكل الصارم (§4 + OP3 §4 — قرار موثق بإيقاف v41/v42):
     OP1 iff contractVersion === "OP1" حرفياً. الباك v44 يبث OP1 على
     القراءات الثلاث (SHIPPING-CONTRACT-OP1 §2: غير OP1 أو مجموعة خارج
     §3 = contractMismatch — توقف + رسالة صريحة، بلا تخمين).
     الحقول القديمة (statusCode/statusReasonCode/labelAr/messageAr) تبقى
     على السلك انتقالياً لكنها لا تُقرأ أبداً — لا استنتاج مرحلة من
     statusCode أو الوقت، وprogressStage:null الصريحة تبقى null.
     وجود حقل واحد (progressStage/detail) لا يثبت عقداً كاملاً. */
  var cvRaw = strOf(p.contractVersion, p.ContractVersion);
  var isOP1Shape = cvRaw === "OP1";
  if (!isOP1Shape) {
    return op1ContractMismatch(p, simulated, isPublic, cvRaw);
  }
  var group = strOf(p.status, p.Status, p.group, p.Group);
  var rawGroup = group;
  if (OP1_GROUPS.indexOf(group) === -1) group = "";
  var full = p.isFullyDelivered !== undefined ? boolOf(p.isFullyDelivered) :
    (p.IsFullyDelivered !== undefined ? boolOf(p.IsFullyDelivered) : (group === "Delivered"));
  var stageRaw = (p.progressStage !== undefined ? p.progressStage : p.ProgressStage);
  var stage = op1StrictStage(stageRaw);
  /* Half Delivered لا يأخذ stage=4 أبداً — ولو أرسله الباك خطأً. */
  var half = group === "Delivered" && full === false;
  if (half && stage === 4) stage = null;
  var voucher = strOf(p.voucherNo, p.VoucherNo, p.trackingNumber);
  var hasVoucher = p.hasVoucher !== undefined ? boolOf(p.hasVoucher) :
    (p.HasVoucher !== undefined ? boolOf(p.HasVoucher) : !!voucher);
  var ps = (p.pollAfterSeconds != null ? Number(p.pollAfterSeconds) : (p.PollAfterSeconds != null ? Number(p.PollAfterSeconds) : NaN));
  if (!Number.isFinite(ps) || ps < 0) ps = NaN;
  var pollMs = (p.pollIntervalMs != null && Number(p.pollIntervalMs) > 0) ? Number(p.pollIntervalMs) : NaN;
  if (!Number.isFinite(pollMs) || pollMs <= 0) {
    pollMs = Number.isFinite(ps) && ps > 0 ? Math.round(ps * 1000) : SHIPMENT_ACTIVE_POLL_MS;
  }
  pollMs = Math.max(SHIPMENT_POLL_MIN_MS, Math.min(SHIPMENT_POLL_MAX_MS, pollMs));
  var sp = null;
  if (p.shouldPoll !== undefined && p.shouldPoll !== null) sp = boolOf(p.shouldPoll);
  else if (p.ShouldPoll !== undefined && p.ShouldPoll !== null) sp = boolOf(p.ShouldPoll);
  var cv = strOf(p.contractVersion, p.ContractVersion);
  var out = {
    contractVersion: cv || "OP1",
    voucherNo: voucher,
    hasVoucher: !!hasVoucher,
    group: group,
    detail: strOf(p.detail, p.Detail),
    detailAr: strOf(p.detailAr, p.DetailAr),
    isFullyDelivered: !!full,
    halfDelivered: !!half,
    exceptional: (group === "Returned" || group === "Cancelled"),
    progressStage: stage,
    needsAttention: boolOf(p.needsAttention !== undefined ? p.needsAttention : p.NeedsAttention),
    lastUpdatedAt: strOf(p.lastUpdatedAt, p.LastUpdatedAt, p.updatedAt),
    isStale: boolOf(p.isStale !== undefined ? p.isStale : p.IsStale),
    shouldPoll: (sp === null || sp === undefined) ? null : !!sp,
    pollAfterSeconds: Number.isFinite(ps) ? ps : Math.round(pollMs / 1000),
    pollIntervalMs: pollMs,
    canRequestCancellation: boolOf(p.canRequestCancellation !== undefined ? p.canRequestCancellation : p.CanRequestCancellation),
    simulated: !!simulated
  };
  if (!isPublic) {
    out.orderId = p.orderId != null ? Number(p.orderId) : (p.OrderId != null ? Number(p.OrderId) : 0);
    out.invoiceNumber = strOf(p.invoiceNumber, p.InvoiceNumber, p.invoiceNo, p.InvoiceNo);
    /* تاريخ التسليم المتوقع للمسجل فقط — إن توفر فعلاً من الباك. */
    var edd = strOf(p.expectedDeliveryDate, p.ExpectedDeliveryDate);
    if (edd) out.expectedDeliveryDate = edd;
  }
  out.contractMismatch = !!(cv && cv !== "OP1") || !!(rawGroup && !group);
  return out;
}

/* ★ OP3 §4: مخرج كسر العقد — أي نسخة حاضرة غير OP1 (v41/v42/مجهولة)
   أو غيابها. نفس البنية المطبعة بلا تخمين: مجموعة فارغة + مرحلة null +
   contractMismatch=true (الصفحات تعرض رسالتها وتوقف التلقيح).
   الحقول القديمة لا تُقرأ إطلاقاً — حتى لو حمل الرد statusCode معروفاً. */
export function op1ContractMismatch(payload, simulated, isPublic, cvRaw) {
  const p = payload || {};
  function strOf() {
    for (let i = 0; i < arguments.length; i++) {
      const v = arguments[i];
      if (v != null && String(v) !== "") return String(v);
    }
    return "";
  }
  var voucher = strOf(p.voucherNo, p.VoucherNo, p.trackingNumber);
  var hasVoucher = p.hasVoucher !== undefined ? !!p.hasVoucher :
    (p.HasVoucher !== undefined ? !!p.HasVoucher : !!voucher);
  var out = {
    contractVersion: String(cvRaw || ""),
    voucherNo: voucher,
    hasVoucher: !!hasVoucher,
    group: "",
    detail: strOf(p.detail, p.Detail),
    detailAr: strOf(p.detailAr, p.DetailAr),
    isFullyDelivered: false,
    halfDelivered: false,
    exceptional: false,
    progressStage: null,
    needsAttention: false,
    lastUpdatedAt: strOf(p.lastUpdatedAt, p.LastUpdatedAt, p.updatedAt),
    isStale: false,
    shouldPoll: false,
    pollAfterSeconds: 0,
    pollIntervalMs: SHIPMENT_POLL_MIN_MS,
    canRequestCancellation: false,
    simulated: !!simulated,
    contractMismatch: true,
    rejectedVersion: String(cvRaw || "")
  };
  if (!isPublic) {
    out.orderId = p.orderId != null ? Number(p.orderId) : (p.OrderId != null ? Number(p.OrderId) : 0);
    out.invoiceNumber = strOf(p.invoiceNumber, p.InvoiceNumber, p.invoiceNo, p.InvoiceNo);
  }
  return out;
}

/* محول الأشكال القديمة (v41/v42) — ★ OP3 §4: موقوف نهائياً (قرار موثق).
   أُبقيت الدالة كغلاف رقيق يُرجع مخرج كسر العقد نفسه ليتعطل أي استدعاء
   قديم بأمان بدل التخمين الصامت — لا تُستعمل في أي مسار حي، وستُحذف
   مع اختباراتها في الجولة القادمة بعد تثبيت CI أخضر. */
export function op1FromLegacyV41(payload, simulated, isPublic) {
  var raw = payload || {};
  var cv = raw.contractVersion != null ? String(raw.contractVersion) : (raw.ContractVersion != null ? String(raw.ContractVersion) : "");
  return op1ContractMismatch(raw, simulated, isPublic, cv);
}

/* قرار المتابعة لشحنة OP1: shouldPoll=false يوقف فوراً؛ النهائية
   (Delivered/Cancelled/Returned) توقف؛ وإلا الحدود المعتادةة. */
export function shouldContinueOP1Poll(input) {
  var o = input || {};
  if (o.contractMismatch === true) return { cont: false, reason: "contract-mismatch" };
  if (o.shouldPoll === false) return { cont: false, reason: "server-stop" };
  if (isOP1Final(o.group)) return { cont: false, reason: "final" };
  if (o.departed === true) return { cont: false, reason: "departed" };
  var attempts = Number(o.attempts);
  var maxA = o.maxAttempts != null ? Number(o.maxAttempts) : SHIPMENT_POLL_MAX_ATTEMPTS;
  if (Number.isFinite(maxA) && Number.isFinite(attempts) && attempts >= maxA) return { cont: false, reason: "budget" };
  var wall = o.maxDurationMs != null ? Number(o.maxDurationMs) : SHIPMENT_POLL_MAX_DURATION_MS;
  var start = Number(o.startedAtMs);
  var now = o.nowMs != null ? Number(o.nowMs) : Date.now();
  if (Number.isFinite(wall) && wall > 0 && Number.isFinite(start) && start > 0) {
    if (now - start >= wall) return { cont: false, reason: "wall" };
  }
  return { cont: true };
}

/* نص التفصيل للعميل: detailAr الباك أولاً، ثم labelAr الاحتياطي، ثم
   label المجموعة. Half Delivered نصها الثابت «تم التسليم جزئيًا». */
export function op1DetailText(shipment, lang) {
  const o = shipment || {};
  if (o.group === "Delivered" && o.isFullyDelivered === false) {
    return lang === "en" ? "Partially delivered" : "تم التسليم جزئيًا";
  }
  if (lang === "en") {
    if (o.detail) return String(o.detail);
    return op1GroupMeta(o.group, "en").label;
  }
  if (o.detailAr) return String(o.detailAr);
  if (o.detail) return String(o.detail);
  return op1GroupMeta(o.group, "ar").label;
}

/* أخطاء التتبع الآمنة (علني/مسجل) — 429 يحترم retryAfter، و404/503
   برسائل مناسبة. لا تحويل لملغاة أبداً. */
export function classifyTrackingError(err, isPublic) {
  const data = (err && err.response && err.response.data) || {};
  const st = Number((err && err.status) || (err && err.response && err.response.status) || 0) || 0;
  const raw = String(data.code || data.reason || data.errorCode || data.error_code || "").trim().toLowerCase();
  const norm = raw.replace(/-/g, "_");
  if (norm === "address_mapping_required") {
    return { kind: "address_mapping_required", message: "عنوانك المحفوظ يحتاج استكمال ربط التوصيل (الإمارة والمنطقة) قبل طلب جديد." };
  }
  if (norm === "shipping_not_supported") {
    return { kind: "shipping_not_supported", message: "هذه المنطقة غير مدعومة للتوصيل حالياً — اختر منطقة أخرى." };
  }
  if (!st || st === 0) {
    const code = String((err && err.code) || "");
    if (/TIMEOUT|ECONNABORTED/i.test(code)) {
      return { kind: "timeout", message: "تعذّر تحميل حالة الشحنة — تحقق من الاتصال ثم أعد المحاولة." };
    }
    if (typeof err !== "undefined" && err && err.name === "AbortError") return { kind: "aborted", message: "" };
    return { kind: "network", message: "تعذّر تحميل حالة الشحنة — تحقق من الاتصال ثم أعد المحاولة." };
  }
  if (st === 404) {
    return isPublic
      ? { kind: "not_found", message: "رقم الشحنة غير موجود — تحقق من الرقم وحاول مجدداً." }
      : { kind: "not_found", message: "لا توجد شحنة مسجلة لهذا الطلب بعد — غيابها الآن طبيعي." };
  }
  if (st === 429) {
    var wait = Number(data.retryAfter || data.retry_after || data.RetryAfter || 0);
    var suffix = Number.isFinite(wait) && wait > 0 ? " (حاول بعد " + Math.round(wait) + " ثانية)" : "";
    return { kind: "rate_limited", message: "طلبات كثيرة في وقت قصير — انتظر قليلاً ثم أعد المحاولة." + suffix, retryAfter: Number.isFinite(wait) ? wait : 0 };
  }
  if (st === 503) {
    return { kind: "service_unavailable", message: "خدمة الشحن غير متاحة مؤقتًا — حاول لاحقًا. طلبك محفوظ ولا يتأثر." };
  }
  if (st === 422) {
    return { kind: "attention", message: "الشحنة تحتاج استكمالًا — راجع التفاصيل أدناه." };
  }
  return { kind: "unknown", message: "تعذّر قراءة حالة الشحنة الآن — حاول مجدداً بعد قليل." };
}

/* ---------- شبكة OP1: علني + مسجل (كاش + مشاركة وعد) ---------- */

var op1ShipmentCache = {};

function mockTrackingOP1(voucherNo, signed) {
  var v = String(voucherNo == null || voucherNo === "" ? "DEMO-0000" : voucherNo);
  var out = {
    contractVersion: "OP1",
    voucherNo: v,
    hasVoucher: true,
    status: "InTheWay",
    detail: "InTransit",
    detailAr: "الشحنة في الطريق إليك",
    isFullyDelivered: false,
    progressStage: 3,
    needsAttention: false,
    lastUpdatedAt: new Date().toISOString(),
    isStale: false,
    shouldPoll: true,
    pollAfterSeconds: Math.round(SHIPMENT_ACTIVE_POLL_MS / 1000),
    canRequestCancellation: !!signed,
    simulated: true
  };
  if (signed) {
    out.orderId = 1;
    out.invoiceNumber = "AY-1";
  }
  return out;
}

/* ★ تتبع علني برقم الشحنة — بلا توكن وبلا PII. POST /api/shipping/tracking.
   الرد يُبنى صراحة بالحقول العامةة فقط (دفاعياً حتى لو أرسل الباك زائداً). */
export function fetchPublicTracking(voucherNo, opts) {
  const o = opts || {};
  const v = String(voucherNo == null ? "" : voucherNo).trim();
  if (!v) return Promise.reject(new Error("missing voucher"));
  if (SHIPPING_SIMULATION) return Promise.resolve(normalizeShipmentOP1(mockTrackingOP1(v, false), true, true));
  if (!API_BASE_URL) return Promise.reject(new Error("تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API"));
  const ctrl = (o.signal) || null;
  var timeoutMs = Number(o.timeoutMs) > 0 ? Number(o.timeoutMs) : 15000;
  var timer = 0;
  var aborted = false;
  var p = new Promise(function (resolve, reject) {
    if (ctrl && ctrl.aborted) { reject(Object.assign(new Error("أُلغي الطلب"), { name: "AbortError", code: "EABORTED" })); return; }
    function onAbort() {
      aborted = true;
      try { if (timer) clearTimeout(timer); } catch (e) {}
      reject(Object.assign(new Error("أُلغي الطلب"), { name: "AbortError", code: "EABORTED" }));
    }
    if (ctrl) { try { ctrl.addEventListener("abort", onAbort, { once: true }); } catch (e) {} }
    if (timeoutMs > 0) {
      timer = setTimeout(function () {
        aborted = true;
        try { if (ctrl) ctrl.removeEventListener("abort", onAbort); } catch (e) {}
        reject(Object.assign(new Error("انتهت مهلة الاتصال بالخادم"), { code: "ECONNABORTED" }));
      }, timeoutMs);
    }
    fetch(API_BASE_URL + ENDPOINTS.shippingTracking(), {
      method: "POST",
      headers: { Accept: "application/json", "Content-Type": "application/json", "ngrok-skip-browser-warning": "true" },
      body: JSON.stringify({ voucherNo: v }),
    }).then(function (res) {
      if (aborted) return;
      try { if (timer) clearTimeout(timer); } catch (e) {}
      try { if (ctrl) ctrl.removeEventListener("abort", onAbort); } catch (e) {}
      res.text().then(function (text) {
        var payload = null;
        try { payload = text ? JSON.parse(text) : null; } catch (e) { payload = null; }
        if (!res.ok) {
          const err = new Error("tracking error");
          err.name = "ApiError";
          err.status = res.status;
          err.response = { status: res.status, data: payload };
          reject(err);
          return;
        }
        try { resolve(normalizeShipmentOP1(payload, false, true)); }
        catch (e) { reject(e); }
      }, reject);
    }, function (e) {
      if (aborted) return;
      try { if (timer) clearTimeout(timer); } catch (e2) {}
      reject(e);
    });
  });
  return p;
}

/* ★ أحدث شحنة للمسجل — GET /api/orders/latest/shipment (حتى قبل voucher). */
export async function fetchLatestShipment(opts) {
  const o = opts || {};
  if (SHIPPING_SIMULATION) return normalizeShipmentOP1(mockTrackingOP1("", true), true, false);
  const res = await authFetch(ENDPOINTS.latestOrderShipment(), { method: "GET", signal: o.signal, timeoutMs: o.timeoutMs });
  const payload = await readJson(res);
  if (!res.ok) throwShipping(res, payload);
  return normalizeShipmentOP1(payload, false, false);
}

/* ★ شحنة طلب مسجل — GET /api/orders/{orderId}/shipment مع مشاركة الوعد. */
export function fetchOrderShipmentOP1(orderId, opts) {
  const o = opts || {};
  const k = "o:" + String(Number(orderId) || orderId || "");
  if (!k || k === "o:") return Promise.reject(new Error("missing order"));
  const hit = op1ShipmentCache[k];
  if (hit && hit.data && !o.force) return Promise.resolve(hit.data);
  if (hit && hit.promise && !o.force) return hit.promise;
  const p = (async function () {
    if (SHIPPING_SIMULATION) return normalizeShipmentOP1(mockTrackingOP1("DEMO-0000", true), true, false);
    const res = await authFetch(ENDPOINTS.orderShipment(String(Number(orderId) || orderId)), { method: "GET", signal: o.signal, timeoutMs: o.timeoutMs });
    const payload = await readJson(res);
    if (!res.ok) throwShipping(res, payload);
    return normalizeShipmentOP1(payload, false, false);
  })();
  op1ShipmentCache[k] = { at: 0, data: (hit && hit.data) || null, promise: p };
  return p.then(function (norm) {
    norm.orderId = Number(orderId) || norm.orderId || 0;
    op1ShipmentCache[k] = { at: Date.now(), data: norm, promise: null };
    return norm;
  }, function (e) {
    if (op1ShipmentCache[k] && op1ShipmentCache[k].promise === p) {
      op1ShipmentCache[k] = { at: 0, data: (hit && hit.data) || null, promise: null };
    }
    throw e;
  });
}

export function clearOP1ShipmentCacheFor(key) {
  const k = String(key == null ? "" : key);
  if (k && op1ShipmentCache["o:" + k]) delete op1ShipmentCache["o:" + k];
}

export function clearOP1ShipmentCache() {
  op1ShipmentCache = {};
}
